<?php
namespace App\Console\Commands;use App\Models\BackupRecord;use Illuminate\Console\Command;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;
class AmerBackupCommand extends Command{protected $signature='amer:backup {--name=automatic}';protected $description='Create an encrypted application-data backup manifest';public function handle():int{$disk=config('amer_operations.backup_disk');$name=$this->option('name').'-'.now('Asia/Dhaka')->format('Ymd-His').'.json';$payload=json_encode(['created_at'=>now()->toIso8601String(),'app'=>config('app.name'),'database'=>config('database.default')],JSON_PRETTY_PRINT);$encrypted=encrypt($payload);$path='backups/'.$name.'.enc';Storage::disk($disk)->put($path,$encrypted);BackupRecord::create(['uuid'=>(string)Str::uuid(),'name'=>$name,'disk'=>$disk,'path'=>$path,'size'=>strlen($encrypted),'checksum'=>hash('sha256',$encrypted),'status'=>'completed','completed_at'=>now()]);$this->info('Encrypted backup manifest created.');return self::SUCCESS;}}
